// Corpus generator for category "tags-anchors".
// Explicit tags (!!str !!int !!float !!bool !!null !!binary !!timestamp !!set
// !!omap !!pairs !!seq !!map) on compatible AND incompatible node kinds,
// verbatim tags, unknown local tags, %TAG directives, anchors/aliases
// (reuse, scalars vs collections, recursion, flow collections, tag+anchor).
import { writeFileSync, mkdirSync } from 'node:fs';

const OUT = '/workspace/probe/corpus/tags-anchors';

const cases = [
  // ---------- core tags on compatible kinds ----------
  '!!str hello',
  '!!str 5',
  '!!str "5"',
  '!!str true',
  '!!str 2001-12-14',
  '!!int 7',
  '!!int "7"',
  '!!int 0x1F',
  '!!int 0o17',
  '!!int 1_000',
  '!!int -0',
  '!!float 3',
  '!!float 3.5',
  '!!float "1e3"',
  '!!float .inf',
  '!!float -.INF',
  '!!float .nan',
  '!!float 1:30',
  '!!bool yes',
  '!!bool off',
  '!!bool TRUE',
  '!!null ""',
  '!!null ~',
  '!!null null',
  '!!null notnull',
  '!!binary "aGVsbG8="',
  '!!binary |\n  R0lG\n  ODlh\n',
  '!!binary ""',
  '!!timestamp 2001-12-14',
=== TAIL ===
  if (seen.has(c)) throw new Error('duplicate case: ' + JSON.stringify(c));
  seen.add(c);
  for (let k = 0; k < c.length; k++) {
    if (c.charCodeAt(k) === 0) throw new Error('NUL in case: ' + JSON.stringify(c));
  }
  if (c.startsWith('-')) {
    const firstLine = c.split('\n')[0];
    if (!firstLine.includes(' ')) {
      throw new Error('argparse-hostile case: ' + JSON.stringify(c));
    }
  }
}
if (cases.length < 60) throw new Error('need at least 60 cases, have ' + cases.length);

mkdirSync(OUT, { recursive: true });
cases.forEach((c, i) => {
  const name = String(i + 1).padStart(3, '0') + '.txt';
  writeFileSync(OUT + '/' + name, c);
});
console.log('tags-anchors: wrote ' + cases.length + ' cases to ' + OUT);
