cat > /tmp/check.mjs <<'EOF'
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync } from 'node:fs';
const DIR = '/workspace/probe/corpus/timestamps-binary';
const files = readdirSync(DIR).filter(f=>f.endsWith('.txt')).sort();
let ok=0, fail=0; const errs = new Map(); const outs = new Set();
for (const f of files) {
  const s = readFileSync(DIR+'/'+f, 'utf8');
  try {
    const o = execFileSync('/workspace/dataset/test14_executable', ['--a', s], { encoding:'utf8', stdio:['ignore','pipe','pipe'] });
    ok++; outs.add(o);
  } catch(e) {
    fail++;
    const line = (e.stderr||'').split('\n').filter(l=>/^[A-Za-z_.]*(Error|error)/.test(l.trim())).pop() || 'rc'+e.status;
    errs.set(line.trim().slice(0,90), (errs.get(line.trim().slice(0,90))||0)+1);
  }
}
console.log('files=%d ok=%d fail=%d distinctOkOutputs=%d', files.length, ok, fail, outs.size);
for (const [k,v] of [...errs].sort((a,b)=>b[1]-a[1])) console.log('  %d x %s', v, k);
EOF
node /tmp/check.mjs
